xript.exports.register('later', async function () { await null; return 'later'; });
xript.exports.register('awaitBinding', async function (ms, value) { return await slow(ms, value); });
xript.exports.register('settled', function () { return Promise.resolve('settled'); });
xript.exports.register('race', function () { return Promise.race([slow(60, 'slow'), slow(1, 'fast')]); });
xript.exports.register('seesPromise', async function () { var p = slow(1, 'x'); var real = p instanceof Promise; await p; return real; });
xript.exports.register('startBinding', function (value) { return slow(1, value); });
